query:
query Run($runId: ID!) { runOrError(runId: $runId) { __typename ... on Run { 
  runId status jobName mode creationTime startTime endTime updateTime rootRunId parentRunId
  tags { key value }
  assetSelection { path }
  stats { __typename ... on RunStatsSnapshot { stepsSucceeded stepsFailed materializations enqueuedTime } }
stepStats { stepKey status startTime endTime attempts { startTime endTime } } } ... on RunNotFoundError { message } ... on PythonError { message } } }
